import os, json
session_dir = os.environ['RLM_SESSION_DIR']
path = session_dir + '/../../sessions/' + os.path.basename(session_dir) + '.jsonl'
with open(path, 'r') as f:
    lines = f.readlines()

print(f"Total lines: {len(lines)}")
print()

# Just print all lines
for i, line in enumerate(lines):
    try:
        data = json.loads(line)
        msg_type = data.get('type')
        if msg_type == 'message':
            content = data.get('message', {}).get('content', [])
            for c in content:
                if c.get('type') == 'text':
                    text = c.get('text', '')
                    if 'Test input' in text or 'task-717f6ba0' in text:
                        print(f"Message line {i}: Found task!")
                        print(text)
                    else:
                        print(f"Message line {i}: {msg_type}")
                        # Hold output, just print first few
                        if i < 5:
                            print(text[:200] + "..." if len(text) > 200 else text)
    except Exception as e:
        print(f"Error on line {i}: {e}")
